using UnityEngine;
using UnityEditor;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (s.Page != "inspect" || !s.Has("slide") || s.data.firstFloorRecorded)
                throw new Exception("Unrecorded floor inspection required");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            w.Focus();
            var log = new StringBuilder("Synthetic GameView mouse and keyboard UI; read-only API assertions. No API open/observe/save/load.\n");
            var settings = InputSystem.settings;
            string prior = JsonUtility.ToJson(settings);
            settings.editorInputBehaviorInPlayMode = InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
            settings.backgroundBehavior = InputSettings.BackgroundBehavior.IgnoreFocus;
            var kb = InputSystem.AddDevice<Keyboard>();
            var mouse = InputSystem.AddDevice<Mouse>();
            kb.MakeCurrent();
            mouse.MakeCurrent();
            var eye = s.eye.transform.rotation;
            var p = s.movement.transform.position;
            var q = new Queue<Action>();
            Action<bool, string> check = (v, m) =>
            {
                log.AppendLine((v ? "PASS " : "FAIL ") + m);
                if (!v)
                    throw new Exception(m);
            };
            Action<Key> key = k => InputSystem.QueueStateEvent(kb, new KeyboardState(k));
            Action release = () => InputSystem.QueueStateEvent(kb, new KeyboardState());
            Action<float, float> click = (x, y) =>
            {
                var at = new Vector2(x * Screen.width / 1200f, y * Screen.height / 800f + 55);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = at});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = at});
            };
            Action<string> shot = n => ScreenCapture.CaptureScreenshot("Test/Output/CleanCheckout/" + n + ".png");
            q.Enqueue(() =>
            {
                check(s.data.introAccepted && s.InspectionCount == 1, "intro accepted; only first floor acquired");
                shot("first-floor-before-note");
            });
            q.Enqueue(() =>
            {
            });
            q.Enqueue(() => InputSystem.QueueStateEvent(mouse, new MouseState{buttons = 1, delta = new Vector2(120, 35)}));
            q.Enqueue(() =>
            {
                InputSystem.QueueStateEvent(mouse, new MouseState{scroll = new Vector2(0, 120)});
            });
            q.Enqueue(() =>
            {
                InputSystem.QueueStateEvent(mouse, new MouseState());
                check(Quaternion.Angle(eye, s.eye.transform.rotation) < .001f, "inspect rotate/zoom leaves player camera still");
                shot("first-floor-rotated-zoomed");
            });
            q.Enqueue(() => click(900, 318));
            q.Enqueue(() =>
            {
                check(s.data.firstFloorRecorded && s.Record("slide").observations.Count == 2, "UI records directly visible floor features");
                check(s.InspectionCount == 1 && s.data.trials.Count == 0 && s.data.mapping.Count == 0, "no unseen evidence/solution added");
                shot("first-floor-recorded");
            });
            q.Enqueue(() =>
            {
            });
            q.Enqueue(() => key(Key.R));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "" && s.CurrentObjective.StartsWith("P"), "R returns; one next action is notes");
                shot("first-note-reminder");
            });
            q.Enqueue(() =>
            {
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier" && s.data.firstNotesReviewed, "P opens actual note and advances tutorial");
                shot("first-note-dossier");
            });
            q.Enqueue(() =>
            {
            });
            q.Enqueue(() =>
            {
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "" && s.CurrentObjective.Contains("điện thoại"), "next objective is phone only");
                shot("second-objective");
            });
            q.Enqueue(() => key(Key.F5));
            q.Enqueue(() =>
            {
                release();
                check(File.Exists(s.SavePath), "F5 writes only technical r107 profile");
            });
            q.Enqueue(() => key(Key.F6));
            q.Enqueue(() =>
            {
                release();
                check(s.data.firstFloorRecorded && s.data.firstNotesReviewed && s.Has("slide") && !s.Has("phone"), "F6 keeps tutorial progress and acquired note only");
                check(Vector3.Distance(p, s.movement.transform.position) < .05f, "load preserves midgame saved position");
            });
            double next = EditorApplication.timeSinceStartup + 1;
            EditorApplication.CallbackFunction f = null;
            Action finish = () =>
            {
                EditorApplication.update -= f;
                InputSystem.RemoveDevice(kb);
                InputSystem.RemoveDevice(mouse);
                JsonUtility.FromJsonOverwrite(prior, settings);
                File.WriteAllText("Test/Output/CleanCheckout/onboarding-ui-complete.txt", log.ToString());
            };
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + 1.1;
                try
                {
                    if (q.Count == 0)
                    {
                        finish();
                        return;
                    }

                    q.Dequeue()();
                }
                catch (Exception e)
                {
                    log.AppendLine("FAIL " + e);
                    finish();
                }
            };
            EditorApplication.update += f;
            r.Log("Started targeted note/rotate/zoom/P/save/load UI continuation");
        }
    }
}

